"""Treatment setup and delivery functions. These functions are called from the top level
IntegrityService interface. They are not intended to be called directly from a test script"""

import interops.libraries.integrity.pages.common_menu_bars as CommonMenuPgObj
import interops.libraries.integrity.beam_states_constants as BeamStates
from interops.libraries.icom.icom_th import iCOM_cat as IcomTest
from interops.libraries.integrity.linac_fkp import Linac_fkp
import logging
import time
import math
import squishtest3 as sq

logger = logging.getLogger(__name__)


def _setup_gantry_asu_with_fkpid(linac_fkp_obj: Linac_fkp, icom_obj: IcomTest) -> None:
    '''
    Performs Gantry ASU using the Function Keypad Interface hardware device
    until the 'Out of Tolerance' inhibit is cleared. A timeout of 75 seconds
    is set as this is roughly the time the gantry takes to do a complete
    rotation.

    Args:
        linac_fkp_obj (Linac_fkp): Linac_fkp object used to perform the
                                   gantry ASU via the FKPID device
        icom_obj (iCOM_cat): iCOM_cat test object used to read the list
                             of inhibits
    '''

    number_of_tries = 2
    while CommonMenuPgObj.StatusIndicator().get_inhibits() not in [
        "Settings Not Confirmed",
        "",
        "Field Incomplete",
        "Missing ID"] and number_of_tries != 0:
        logger.info("ASU ATTEMPT NO OF TRIES LEFT" + str(number_of_tries))
        linac_fkp_obj.check_fkpid_status()
        linac_fkp_obj.start_asu()
        sq.snooze(5)
        time_to_asu = 75
        while "Out Of Tolerance" in icom_obj.get_inhibits_list() and time_to_asu != 0:
            sq.snooze(1)
            time_to_asu -= 1
        linac_fkp_obj.stop_asu()
        number_of_tries -= 1
        if time_to_asu == 0 and "Out Of Tolerance" in icom_obj.get_inhibits_list():
            logger.info("OUT OF TOLERANCE AFTER 75 SECS, WILL CHECK CONNECTION AND EXIT")
            linac_fkp_obj.check_fkpid_status()
            break


def _setup_gantry_asu_with_crowbar(linac_fkp_obj: Linac_fkp, icom_obj: IcomTest) -> None:
    '''
    Performs Gantry ASU by pressing the Function Keypad 'Auto' button in Crowbar
    until the 'Out of Tolerance' inhibit is cleared. A timeout of 75 seconds
    is set as this is roughly the time the gantry takes to do a complete
    rotation.

    Args:
        linac_fkp_obj (Linac_fkp): Linac_fkp object used to perform the
                                   gantry ASU via Crowbar
        icom_obj (iCOM_cat): iCOM_cat test object used to read the list
                             of inhibits
    '''

    number_of_tries = 2
    while CommonMenuPgObj.StatusIndicator().get_inhibits() not in [
        "Settings Not Confirmed",
        "",
        "Field Incomplete",
        "Missing ID"] and number_of_tries != 0:
        logger.info("CROWBAR ASU ATTEMPT NO " + str(number_of_tries))
        linac_fkp_obj.crowbar.initiate_gantry_asu()
        sq.snooze(5)
        time_to_asu = 75
        while "Out Of Tolerance" in icom_obj.get_inhibits_list() and time_to_asu != 0:
            sq.snooze(1)
            time_to_asu -= 1
        linac_fkp_obj.crowbar.disengage_gantry_asu()
        number_of_tries -= 1
        if time_to_asu == 0 and "Out Of Tolerance" in icom_obj.get_inhibits_list():
            break


def _treatment_start_beam_with_fkpid(linac_fkp_obj: Linac_fkp) -> bool:
    '''
    Starts beam radiation using the Function Keypad Interface hardware
    device and checks that the linac is in one of the beam running states

    Args:
        linac_fkp_obj (Linac_fkp): Linac_fkp object used to start beam
                                   radiation via the FKPID device

    Returns:
        bool - True if the linac is in a beam running state
    '''
    for n in range(2):
        logger.info("BEAM START ATTEMPT: " + str(n + 1))
        linac_fkp_obj.start_beam()
        sq.snooze(2)
        machine_state = CommonMenuPgObj.StatusIndicator().get_machine_state()
        if machine_state in BeamStates.BEAM_RUNNING_STATES:
            return True
    return False


def _treatment_start_beam_with_crowbar(linac_fkp_obj: Linac_fkp) -> bool:
    '''
    Starts beam radiation by pressing the 'Start' button in
    Crowbar and checks that the linac is in one of the beam
    running states

    Args:
        linac_fkp_obj (Linac_fkp): Linac_fkp object used to start
                                   beam radiation via Crowbar

    Returns:
        bool - True if the linac is in a beam running state
    '''
    try:
        linac_fkp_obj.start_beam()
        sq.snooze(2)
        machine_state = CommonMenuPgObj.StatusIndicator().get_machine_state()
        if machine_state in BeamStates.BEAM_RUNNING_STATES:
            return True
        return False
    except Exception as e:
        logger.info("Error starting beam with crowbar " + str(e))
        return False


def _setup_table_asu_with_crowbar(linac_fkp_obj: Linac_fkp, icom_obj: IcomTest) -> None:
    '''
    Presses and holds down the Table ASU button in Crowbar until the Table Vertical,
    Latitude and Longitude SET values no longer return any values, indicating that
    the Table is now in Tolerance.

    Args:
        linac_fkp_obj (Linac_fkp): Linac_fkp object which contains the Crowbar object
        icom_obj (iCOM_cat): iCOM object used to read the iCOM Vx Table lat, long and
        vertical values

    Returns:
        None
    '''
    # Select the Enable Bars 1 and 2 checkboxes if they are not already checked
    sq.snooze(1)
    linac_fkp_obj.crowbar.enable_hand_held_controller_bars_1()
    sq.snooze(1)
    linac_fkp_obj.crowbar.enable_hand_held_controller_bars_2()
    sq.snooze(1)

    # Uncheck the Room Doors 1 Interlock checkbox to allow for Table ASU
    linac_fkp_obj.crowbar.disengage_interlock_room_doors_1()

    # Table vertical, lateral and longitudinal iCOM Vx SET integer values are returned
    # whilst the table is out of tolerance. Once the table is in tolerance these values will
    # evaluate to False so it should break out of the while loop.
    start_time = time.time()
    asu_timeout = start_time + 60 # 1 minute timeout
    while ((icom_obj.get_Vx_table_vertical(mode="set")) and
            (icom_obj.get_Vx_table_lateral(mode="set")) and
            (icom_obj.get_Vx_table_longitudinal(mode="set"))):
        linac_fkp_obj.crowbar.engage_table_asu()

        # Extra check using the linac status text and timeout to break out of the loop
        # in case any of the loop conditions fail to get evaluated
        if (CommonMenuPgObj.StatusIndicator().get_inhibits() == "Room Doors 1"
            or time.time() > asu_timeout):
            break

    sq.snooze(1)
    linac_fkp_obj.crowbar.disengage_table_asu()

    # Re-enable Room Doors 1 Interlock in preparation for beam delivery
    # Update existing value in the interlocks_to_set dictionary
    linac_fkp_obj.crowbar.engage_interlock_room_doors_1()

def _setup_table_asu_with_fkp_plus_button_in_crowbar(linac_fkp_obj: Linac_fkp, icom_obj: IcomTest,
                                                     asu_timeout: int = 20) -> None:
    '''
    Presses and holds down the plus "+" button in Crowbar until the Table Vertical, Latitude and
    Longitude SET values match the RUN values, indicating that the Table is now in Tolerance.

    Args:
        linac_fkp_obj (Linac_fkp): Linac_fkp object which contains the Crowbar object
        icom_obj (iCOM_cat): iCOM object used to read the iCOM Vx Table lat, long and
        vertical values
        asu_timeout (int): Max time (in seconds) to wait to complete the table ASU operation.

    Returns:
        None
    '''
    # Hold the Crowbar FKP plus "+" button down to Table ASU until the Table vertical, lateral
    # and longitudinal iCOM Vx SET integer values equal the RUN values. Once the table is in
    # tolerance break out of the loop.
    start_time = time.time()
    table_asu_timeout = start_time + asu_timeout # 30 second default timeout
    while ((icom_obj.get_Vx_table_vertical(mode="set") != icom_obj.get_Vx_table_vertical(mode="run")) or
            (icom_obj.get_Vx_table_lateral(mode="set") != icom_obj.get_Vx_table_lateral(mode="run")) or
            (icom_obj.get_Vx_table_longitudinal(mode="set") != icom_obj.get_Vx_table_longitudinal(mode="run"))):
        linac_fkp_obj.crowbar.engage_table_asu_with_fkp_plus_button()

        # Extra check using a timeout to break out of the loop in case any of the loop
        # conditions fail to get evaluated
        if (time.time() > table_asu_timeout):
            break

    sq.snooze(1)
    linac_fkp_obj.crowbar.disengage_table_asu_with_fkp_plus_button()

def _set_table_vertical_with_crowbar(linac_fkp_obj: Linac_fkp, icom_obj: IcomTest, use_user_defined_set_value: bool = False,
                                     set_table_vertical_value: float = 0.0, tolerance: float = 0.2) -> None:
    '''
    Mouse clicks and drags the Crowbar "Height" slider control either up or down in the User Interface Module (UIM)
    section to move the Table vertical (ACTUAL) value to the user specified set_table_vertical_value SET value OR to
    the SET value obtained from the iCOM Vx object.

    Args:
        linac_fkp_obj (Linac_fkp): Linac_fkp object which contains the Crowbar object
        icom_obj (IcomTest): iCOM object used to read the iCOM Vx ACTUAL and SET Table vertical values
        use_user_defined_set_value (bool): If True, use the user defined value to set the ACTUAL table vertical value.
                                           Default is False, which uses the SET value from the iCOM Vx object.
        set_table_vertical_value (float): The user defined value to set the ACTUAL table vertical value.
                                          Default value 0.0 can be left if the use_user_defined_set_value is False.
        tolerance (float): The tolerance value to use when comparing the SET and ACTUAL values. Default is 0.2.
                           NOTE: Do not recommend setting the tolerance any lower than 0.2 as the Crowbar slider
                           is highly sensitive and is difficult to control, resulting in overshooting the target value.
    Returns:
        None
    '''
    if use_user_defined_set_value:
        set_vertical = set_table_vertical_value
    else:
        # Read the SET value from the iCOM Vx object using the SET mode if the user defined value is not specified
        set_vertical = icom_obj.get_Vx_table_vertical(mode="set")

        if set_vertical is not None:
            # NOTE: Due to icom using bipolar scale and integrity using IEC1217 scale, the polarity between what is displayed
            # compared to what is returned is reversed. So to compare it correctly reverse the polarity using the negative "-" sign
            # Only set this to negative for the value obtained from icom Vx SET and not for the user defined value
            set_vertical = -set_vertical
        else:
            set_vertical = None
            logger.info("Table vertical value set to none, exiting method")

    if set_vertical is not None:
        while not math.isclose(set_vertical, -icom_obj.get_Vx_table_vertical(mode="run"), abs_tol = tolerance): # type: ignore
            run_vertical = -icom_obj.get_Vx_table_vertical(mode="run")  # type: ignore

            # Try reducing the slider shift value once the ACTUAL value is close enough to the SET value to refine the slider movement
            slider_shift_value = 4 # This value controls how far to move the slider
            slider_drag_duration = 2 # This value controls how long to drag the slider for
            if math.isclose(set_vertical, -icom_obj.get_Vx_table_vertical(mode="run"), abs_tol = 0.5): # type: ignore
                slider_shift_value = 3
                slider_drag_duration = 1

            if set_vertical > run_vertical:
                # Move the Crowbar slider down to increase the table vertical
                linac_fkp_obj.move_table_vertical(sliderDirection="down", sliderShiftValue=slider_shift_value, dragDuration=slider_drag_duration)
            elif set_vertical < run_vertical:
                # Move the Crowbar slider up to decrease the table vertical
                linac_fkp_obj.move_table_vertical(sliderDirection="up", sliderShiftValue=slider_shift_value, dragDuration=slider_drag_duration)

def _set_table_lateral_with_crowbar(linac_fkp_obj: Linac_fkp, icom_obj: IcomTest, use_user_defined_set_value: bool = False,
                                     set_table_lateral_value: float = 0.0, tolerance: float = 0.2) -> None:
    '''
    Mouse clicks and drags the Crowbar "Lat" slider control either left or right in the User Interface Module (UIM)
    section to move the Table lateral (ACTUAL) value to the user specified set_table_lateral_value SET value OR to
    the SET value obtained from the iCOM Vx object.

    linac_fkp_obj (Linac_fkp): Linac_fkp object which contains the Crowbar object
    icom_obj (IcomTest): iCOM object used to read the iCOM Vx ACTUAL and SET Table lateral values
    use_user_defined_set_value (bool): If True, use the user defined value to set the ACTUAL table lateral value.
                                       Default is False, which uses the SET value from the iCOM Vx object.
    set_table_lateral_value (float): The user defined value to set the ACTUAL table lateral value.
                                     Default value 0.0 can be left if the use_user_defined_set_value is False.
    tolerance (float): The tolerance value to use when comparing the SET and ACTUAL values. Default is 0.2.
                       NOTE: Do not recommend setting the tolerance any lower than 0.2 as the Crowbar slider
                       is highly sensitive and is difficult to control, resulting in overshooting the target value.
    Returns:
        None
    '''
    if use_user_defined_set_value:
        set_lateral = set_table_lateral_value
    else:
        # Read the SET value from the iCOM Vx object using the SET mode if the user defined value is not specified
        set_lateral = icom_obj.get_Vx_table_lateral(mode="set")

    if icom_obj.get_Vx_table_lateral(mode="set") is None and not use_user_defined_set_value:
        set_lateral = None
        logger.info("Table Lateral value set to none, exiting method")

    if set_lateral is not None:
        while not math.isclose(set_lateral, icom_obj.get_Vx_table_lateral(mode="run"), abs_tol = tolerance): # type: ignore
            run_lateral = icom_obj.get_Vx_table_lateral(mode="run")

            # Try reducing the slider shift value once the ACTUAL value is close enough to the SET value to refine the slider movement
            slider_shift_value = 4 # This value controls how far to move the slider
            slider_drag_duration = 2 # This value controls how long to drag the slider for
            if math.isclose(set_lateral, icom_obj.get_Vx_table_lateral(mode="run"), abs_tol = 0.5): # type: ignore
                slider_shift_value = 3
                slider_drag_duration = 1

            if run_lateral is not None:
                if set_lateral > run_lateral:
                    # Move the Crowbar slider to the left to decrease the table lateral
                    linac_fkp_obj.move_table_lateral(sliderDirection="left", sliderShiftValue=slider_shift_value, dragDuration=slider_drag_duration)
                elif set_lateral < run_lateral:
                    # Move the Crowbar slider to the right to increase the table lateral
                    linac_fkp_obj.move_table_lateral(sliderDirection="right", sliderShiftValue=slider_shift_value, dragDuration=slider_drag_duration)

